const climateOf=s=>s.macro>1.04?'偏热':s.macro<.96?'偏冷':'平稳';
// Cash / amount due on the next tier. Progress is 1 on the last house, not capped at the fifth.
function homeGoal(s){const owned=H.houses.findIndex(h=>h.id===s.house),top=owned>=0&&owned===H.houses.length-1,goal=H.houses[top?owned:owned<0?0:owned+1],due=top?0:H.housePrice(s,goal)-H.houseValue(s);return {owned,goal,due,top,progress:due>0?Math.max(0,Math.min(1,s.cash/due)):1};}
