function bpsMark(n,testid){if(n===null)return '';const up=n>=0;return `<span class="${up?'up':'down'}${testid==='goal-change'?' goal-change':''}"${testid?` data-testid="${testid}"`:''}>较上周 ${up?'+':''}${(n/100).toFixed(1)}%</span>`;}
function mergeMilestonesSafe(state,options){try{const r=saves.mergeMilestones(state,options||{});if(!r||r.ok===false)return {ok:false,error:(r&&r.error)||''};return r;}catch(e){if(typeof saves.mergeMilestones!=='function')return {ok:true,pending:true};return {ok:false,error:e.message||String(e)};}}
function loadMilestoneEntries(){try{const r=saves.loadMilestones();const entries=r&&r.ok?(Array.isArray(r.entries)?r.entries:(r.milestones&&Array.isArray(r.milestones.entries)?r.milestones.entries:null)):null;if(entries)return {ok:true,entries};return {ok:false,error:(r&&r.error)||''};}catch(e){return {ok:false,error:typeof saves.loadMilestones==='function'?(e.message||String(e)):''};}}
